BEGIN;
CREATE INDEX ct_distribution_owned_lookup ON public.ct_player_titles(title_id,user_id) WHERE revoked_at IS NULL;
CREATE TABLE public.ct_title_distributions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),admin_id uuid NOT NULL REFERENCES public.ct_profiles(id),title_id text NOT NULL REFERENCES public.ct_titles(id),scope text NOT NULL CHECK(scope IN('players','bots','both')),exclude_owned boolean NOT NULL,total integer NOT NULL CHECK(total>0),processed integer NOT NULL DEFAULT 0 CHECK(processed>=0 AND processed<=total),delivered integer NOT NULL DEFAULT 0 CHECK(delivered>=0 AND delivered<=processed),recipients uuid[] NOT NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'ready' CHECK(status IN('ready','running','paused','completed','cancelled')),next_run_at timestamptz NOT NULL DEFAULT now(),last_error text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(cardinality(recipients)=total));
ALTER TABLE public.ct_title_distributions ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.ct_title_distributions FROM PUBLIC,anon,authenticated;
CREATE INDEX ct_title_distributions_recent ON public.ct_title_distributions(admin_id,created_at DESC);
CREATE INDEX ct_title_distributions_next ON public.ct_title_distributions(next_run_at DESC);
CREATE FUNCTION public.ct_title_distribution_eligible(p_title text,p_scope text,p_exclude boolean) RETURNS SETOF uuid LANGUAGE sql STABLE SET search_path='' AS $$
 SELECT p.id FROM public.ct_profiles p WHERE(p_scope='both' OR p_scope='bots' AND p.is_bot OR p_scope='players' AND NOT p.is_bot) AND NOT EXISTS(SELECT 1 FROM public.ct_suspensions WHERE user_id=p.id) AND(public.ct_is_owner() OR NOT EXISTS(SELECT 1 FROM public.ct_owners WHERE user_id=p.id)) AND(NOT p.is_bot OR EXISTS(SELECT 1 FROM public.ct_bots WHERE user_id=p.id AND active)) AND(NOT p.is_bot OR(SELECT rarity FROM public.ct_titles WHERE id=p_title)<8) AND(NOT p_exclude OR NOT EXISTS(SELECT 1 FROM public.ct_player_titles WHERE user_id=p.id AND title_id=p_title AND revoked_at IS NULL));
$$;
CREATE FUNCTION public.ct_admin_title_audience(p_title text,p_scope text DEFAULT 'both',p_exclude boolean DEFAULT true) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN IF NOT public.ct_is_admin() THEN RAISE EXCEPTION 'Administrator required';END IF;IF p_scope IS NULL OR p_scope NOT IN('players','bots','both') OR p_exclude IS NULL OR NOT EXISTS(SELECT 1 FROM public.ct_titles WHERE id=p_title) THEN RAISE EXCEPTION 'Sélection de distribution invalide';END IF;RETURN jsonb_build_object('eligible',(SELECT count(*) FROM public.ct_title_distribution_eligible(p_title,p_scope,p_exclude)));END $$;
CREATE FUNCTION public.ct_title_distribution_json(p_job uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$ SELECT jsonb_build_object('id',d.id,'title_id',d.title_id,'title_name',t.name,'rarity',t.rarity,'scope',d.scope,'total',d.total,'processed',d.processed,'delivered',d.delivered,'skipped',d.processed-d.delivered,'status',d.status,'last_error',d.last_error,'created_at',d.created_at) FROM public.ct_title_distributions d JOIN public.ct_titles t ON t.id=d.title_id WHERE d.id=p_job $$;
CREATE FUNCTION public.ct_admin_title_distributions() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT public.ct_is_admin() THEN RAISE EXCEPTION 'Administrator required';END IF;RETURN coalesce((SELECT jsonb_agg(public.ct_title_distribution_json(x.id) ORDER BY created_at DESC) FROM(SELECT id,created_at FROM public.ct_title_distributions WHERE admin_id=auth.uid() OR public.ct_is_owner() ORDER BY created_at DESC LIMIT 30)x),'[]');END $$;
CREATE FUNCTION public.ct_admin_title_distribution_start(p_operation_id uuid,p_title text,p_count integer,p_scope text DEFAULT 'both',p_exclude boolean DEFAULT true,p_reason text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE u uuid:=auth.uid();q jsonb:=jsonb_build_object('kind','title_distribution_start','title',p_title,'count',p_count,'scope',p_scope,'exclude',p_exclude,'reason',p_reason);r jsonb;ids uuid[];job uuid;
BEGIN IF NOT public.ct_is_admin() THEN RAISE EXCEPTION 'Administrator required';END IF;p_reason:=public.ct_admin_reason(p_reason);IF length(trim(coalesce(p_reason,''))) NOT BETWEEN 8 AND 1000 THEN RAISE EXCEPTION 'Justification required';END IF;PERFORM pg_advisory_xact_lock(173,14);r:=public.ct_replay(u,p_operation_id,q);IF r IS NOT NULL THEN RETURN r;END IF;
 PERFORM public.ct_admin_title_audience(p_title,p_scope,p_exclude);IF p_count IS NULL OR p_count<1 THEN RAISE EXCEPTION 'Choisissez un nombre de destinataires positif';END IF;
 SELECT array_agg(id) INTO ids FROM(SELECT e.id FROM public.ct_title_distribution_eligible(p_title,p_scope,p_exclude)e(id) ORDER BY gen_random_uuid() LIMIT p_count)x;
 IF cardinality(ids) IS DISTINCT FROM p_count THEN RAISE EXCEPTION 'Pas assez de destinataires éligibles pour cette sélection';END IF;
 INSERT INTO public.ct_title_distributions(admin_id,title_id,scope,exclude_owned,total,recipients,reason) VALUES(u,p_title,p_scope,p_exclude,p_count,ids,p_reason) RETURNING id INTO job;
 INSERT INTO public.ct_admin_audit_logs(admin_id,action,target,reason,details) VALUES(u,'random_title_distribution_start',job::text,p_reason,jsonb_build_object('title',p_title,'count',p_count,'scope',p_scope,'exclude_owned',p_exclude));r:=public.ct_title_distribution_json(job);INSERT INTO public.ct_operations(user_id,operation_id,request,result) VALUES(u,p_operation_id,q,r);RETURN r;
END $$;
CREATE FUNCTION public.ct_admin_title_distribution_step(p_operation_id uuid,p_job uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' SET statement_timeout='25s' AS $$
DECLARE u uuid:=auth.uid();q jsonb:=jsonb_build_object('kind','title_distribution_step','job',p_job);r jsonb;b public.ct_title_distributions;n integer;issued integer;allowed_at timestamptz;
BEGIN IF NOT public.ct_is_admin() THEN RAISE EXCEPTION 'Administrator required';END IF;PERFORM pg_advisory_xact_lock(173,14);SELECT * INTO b FROM public.ct_title_distributions WHERE id=p_job AND(admin_id=u OR public.ct_is_owner()) FOR UPDATE;IF b.id IS NULL THEN RAISE EXCEPTION 'Distribution introuvable';END IF;r:=public.ct_replay(u,p_operation_id,q);IF r IS NOT NULL THEN RETURN r;END IF;
 IF b.status NOT IN('ready','running') THEN RETURN jsonb_build_object('ok',false,'job',public.ct_title_distribution_json(p_job));END IF;
 SELECT next_run_at INTO allowed_at FROM public.ct_title_distributions ORDER BY next_run_at DESC LIMIT 1;IF allowed_at>clock_timestamp() THEN RETURN jsonb_build_object('deferred',true,'job',public.ct_title_distribution_json(p_job));END IF;
 n:=least(100,b.total-b.processed);
 BEGIN
  IF pg_database_size(current_database())>350000000 THEN RAISE EXCEPTION 'Création suspendue : seuil prudent de 350 Mo atteint dans la base';END IF;
  -- Revalidate only this bounded recipient slice, using indexed ownership checks.
  INSERT INTO public.ct_player_titles(user_id,title_id,source)
  SELECT p.id,b.title_id,'distribution:'||b.id::text FROM unnest(b.recipients[b.processed+1:b.processed+n]) x(id) JOIN public.ct_profiles p ON p.id=x.id
  WHERE NOT EXISTS(SELECT 1 FROM public.ct_suspensions WHERE user_id=p.id) AND(public.ct_is_owner() OR NOT EXISTS(SELECT 1 FROM public.ct_owners WHERE user_id=p.id)) AND(NOT p.is_bot OR EXISTS(SELECT 1 FROM public.ct_bots WHERE user_id=p.id AND active)) AND(NOT p.is_bot OR(SELECT rarity FROM public.ct_titles WHERE id=b.title_id)<8) AND(NOT b.exclude_owned OR NOT EXISTS(SELECT 1 FROM public.ct_player_titles WHERE user_id=p.id AND title_id=b.title_id AND revoked_at IS NULL));
  GET DIAGNOSTICS issued=ROW_COUNT;
  UPDATE public.ct_title_distributions SET processed=processed+n,delivered=delivered+issued,status=CASE WHEN processed+n=total THEN 'completed' ELSE 'running' END,next_run_at=clock_timestamp()+interval '1 second',last_error=NULL WHERE id=p_job;
  INSERT INTO public.ct_admin_audit_logs(admin_id,action,target,reason,details) VALUES(u,'random_title_distribution_batch',p_job::text,b.reason,jsonb_build_object('processed',n,'delivered',issued,'title',b.title_id));r:=jsonb_build_object('ok',true,'job',public.ct_title_distribution_json(p_job));
 EXCEPTION WHEN OTHERS THEN UPDATE public.ct_title_distributions SET status='paused',last_error=left(SQLERRM,1000) WHERE id=p_job;r:=jsonb_build_object('ok',false,'error',left(SQLERRM,1000),'job',public.ct_title_distribution_json(p_job));END;
 INSERT INTO public.ct_operations(user_id,operation_id,request,result) VALUES(u,p_operation_id,q,r);RETURN r;
END $$;
CREATE FUNCTION public.ct_admin_title_distribution_control(p_operation_id uuid,p_job uuid,p_action text,p_reason text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE u uuid:=auth.uid();q jsonb:=jsonb_build_object('kind','title_distribution_control','job',p_job,'action',p_action,'reason',p_reason);r jsonb;b public.ct_title_distributions;
BEGIN IF NOT public.ct_is_admin() THEN RAISE EXCEPTION 'Administrator required';END IF;p_reason:=public.ct_admin_reason(p_reason);IF length(trim(coalesce(p_reason,''))) NOT BETWEEN 8 AND 1000 THEN RAISE EXCEPTION 'Justification required';END IF;PERFORM pg_advisory_xact_lock(173,14);SELECT * INTO b FROM public.ct_title_distributions WHERE id=p_job AND(admin_id=u OR public.ct_is_owner()) FOR UPDATE;IF b.id IS NULL OR p_action IS NULL OR p_action NOT IN('pause','resume','cancel') THEN RAISE EXCEPTION 'Distribution introuvable';END IF;r:=public.ct_replay(u,p_operation_id,q);IF r IS NOT NULL THEN RETURN r;END IF;
 IF b.status NOT IN('completed','cancelled') THEN UPDATE public.ct_title_distributions SET status=CASE p_action WHEN 'pause' THEN 'paused' WHEN 'resume' THEN 'ready' ELSE 'cancelled' END,last_error=CASE WHEN p_action='resume' THEN NULL ELSE last_error END WHERE id=p_job;END IF;
 INSERT INTO public.ct_admin_audit_logs(admin_id,action,target,reason,details) VALUES(u,'random_title_distribution_control',p_job::text,p_reason,jsonb_build_object('action',p_action));r:=public.ct_title_distribution_json(p_job);INSERT INTO public.ct_operations(user_id,operation_id,request,result) VALUES(u,p_operation_id,q,r);RETURN r;
END $$;
REVOKE ALL ON FUNCTION public.ct_title_distribution_eligible(text,text,boolean),public.ct_admin_title_audience(text,text,boolean),public.ct_title_distribution_json(uuid),public.ct_admin_title_distributions(),public.ct_admin_title_distribution_start(uuid,text,integer,text,boolean,text),public.ct_admin_title_distribution_step(uuid,uuid),public.ct_admin_title_distribution_control(uuid,uuid,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ct_admin_title_audience(text,text,boolean),public.ct_admin_title_distributions(),public.ct_admin_title_distribution_start(uuid,text,integer,text,boolean,text),public.ct_admin_title_distribution_step(uuid,uuid),public.ct_admin_title_distribution_control(uuid,uuid,text,text) TO authenticated;
COMMIT;
